namespace sv_c9f7149318d44616a63d01adfce49d81.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires <see cref="OnChange"/> so all subscribed components re-render
/// when new data arrives — even if they didn't trigger the poll.
/// Scoped lifetime ensures each circuit (user) has independent state.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    /// <summary>Simulates a database query returning a random count 0-15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        _ = warehouseId; // would be used in a real query
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds. Reference-counted so multiple
    /// components can call Start/Stop independently.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1)
            return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0)
            return; // other subscribers still active

        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
        _timer = null;
        _cts = null;
    }

    /// <summary>Restart polling for a different warehouse.</summary>
    public void RestartPolling(string warehouseId)
    {
        var count = _subscriberCount;
        // Force-stop regardless of subscriber count
        _subscriberCount = 0;
        StopPolling();
        _subscriberCount = count;
        if (count > 0)
        {
            _subscriberCount = 0; // StartPolling will increment
            for (var i = 0; i < count; i++)
                StartPolling(warehouseId);
        }
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fire an initial poll immediately so the UI has data right away
        await RefreshAsync(warehouseId);

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync(warehouseId);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task RefreshAsync(string warehouseId)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _subscriberCount = 0;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

