@rendermode InteractiveServer
@using sv_c9f7149318d44616a63d01adfce49d81.Services
@inject CascadingValueSource<WarehouseState> WarehouseSource

<select class="form-select form-select-sm" style="width: 200px;"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.All)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private string _selectedId = WarehouseInfo.All[0].Id;

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
            _selectedId = Warehouse.WarehouseId;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString() ?? WarehouseInfo.All[0].Id;
        var info = WarehouseInfo.All.FirstOrDefault(w => w.Id == id) ?? WarehouseInfo.All[0];

        var newState = new WarehouseState
        {
            WarehouseId = info.Id,
            WarehouseName = info.Name
        };

        await WarehouseSource.NotifyChangedAsync(newState);
    }
}

