@page "/dashboard"
@rendermode InteractiveServer
@using sv_c9f7149318d44616a63d01adfce49d81.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

@if (Warehouse is not null)
{
    <h4 class="mb-3">Current Site: @Warehouse.WarehouseName (@Warehouse.WarehouseId)</h4>

    <div class="card" style="max-width: 320px;">
        <div class="card-body">
            <h5 class="card-title">
                Low-Stock Alerts
                <span class="badge bg-danger rounded-pill ms-2">@AlertService.LowStockCount</span>
            </h5>
            <p class="card-text text-muted">
                Items below minimum stock level. Refreshes every 10 seconds.
            </p>
        </div>
    </div>
}
else
{
    <p><em>No warehouse selected.</em></p>
}

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private string _activeWarehouseId = string.Empty;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        if (Warehouse is null)
            return;

        if (_activeWarehouseId != Warehouse.WarehouseId)
        {
            _activeWarehouseId = Warehouse.WarehouseId;

            // Restart polling for the new warehouse
            if (!string.IsNullOrEmpty(_activeWarehouseId))
            {
                AlertService.RestartPolling(_activeWarehouseId);
            }
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender && Warehouse is not null)
        {
            _activeWarehouseId = Warehouse.WarehouseId;
            AlertService.StartPolling(_activeWarehouseId);
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

